mapper.select:
SELECT , p.ticker, p.name, sp.name AS package_name
FROM domestic_order o
JOIN stock_package sp ON sp.stock_package_id = o.stock_package_id
JOIN domestic_product p ON p.domestic_product_id = o.domestic_product_id
WHERE sp.customer_id = #{customerId}
  AND o.channel = 'CUSTOMER'

  AND o.stock_package_id = #{stockPackageId}

ORDER BY o.processed_at DESC, o.domestic_order_id DESC
LIMIT #{limit}

mapper.update:
UPDATE domestic_stock_balance
SET qty = #{qty}, status = #{status},

    last_purchase_date = GREATEST(COALESCE(last_purchase_date, #{lastPurchaseDate}),
                                  #{lastPurchaseDate}),
    avg_purchase_price = #{avgPurchasePrice}
WHERE domestic_stock_balance_id = #{domesticStockBalanceId}
